function UIFeelingNaughtyDialog:Awake()
    self.GCList = {}
    self:Init3DRobot()
    self:FillSelf()
end

function UIFeelingNaughtyDialog:Init3DRobot()
    local loaderRobotParentNode = ResourceModule.LoadBundleSync('Prefabs/Feeling/NaughtyRobotNode.prefab', nil, true)
    if loaderRobotParentNode and loaderRobotParentNode.IsSuccess then
        local robotParentNodeGo = loaderRobotParentNode:Instantiate()
        -- local robotParentNodeGo = CS.UnityEngine.GameObject.Instantiate(loaderRobotParentNode.ResultObject)--机器人父节点Go,下面有相机，机器人加载到这个下面
        self.roleCamera = robotParentNodeGo.transform:Find("RoleCamera"):GetComponent("Camera")
        self.renderTexture = CS.UnityEngine.RenderTexture.GetTemporary(164, 242, 0, CS.UnityEngine.RenderTextureFormat.Default);
        self.roleCamera.targetTexture = self.renderTexture
        self.ImgAI.texture = self.renderTexture

        local loaderRobot = ResourceModule.LoadBundleSync('Arts/Prefab/whitecatrobot.prefab', nil, true) --机器人
        if loaderRobot and loaderRobot.IsSuccess then
            -- local robotGo = CfUtils.InstantiateGo(loaderRobot.ResultObject, robotParentNodeGo)
            local robotGo = loaderRobot:Instantiate(robotParentNodeGo.transform)
            robotGo.transform.localPosition = Vector3.zero
            self.robotAnim = robotGo.transform:GetComponent(typeof(Animator))
            self.robotAnim:Play("whitecat_idle_wudizuo")
            self.clickAnimTime = CfUtils.GetAnimatorTime(robotGo, "whitecat_select_wudizuo")
            KTool.SetActive(robotGo, true)
        end
        loaderRobot:Release()
        KTool.SetActive(robotParentNodeGo, true)
        table.insert(self.GCList, robotParentNodeGo)
    end
    loaderRobotParentNode:Release()
end

function UIFeelingNaughtyDialog:FillSelf()
    CfUtils.FillText(self.Text, localize("正在匹配相同频率的情绪粒子..."))
    CfUtils.FillText(self.BtnShakeit.transform:Find("Text"), localize("摇一摇"))
    SetButtonAction(self.BtnShakeit, Bind(self, self.OnBtnShakeit))
end

--摇一摇
function UIFeelingNaughtyDialog:OnBtnShakeit()
    --如果没有领红包
    if self._isDontDrawReward then
        GameUtils.Toast(localize("请先领取红包"))
        return
    end

    if self._isDrawing then
        return
    end
    self._isDrawing = true
    --清空一下摇一摇时候的对话缓存
    phoneComp:SetYaoyiyaoReplyIndex({
        curMessageId = 0,
        replyIndexs = {},                        --回复的下标数组
    })

    self._co = cs_coroutine.start(function()
        self:RefeshState()
        self:PlayShakeRobotAnim()
        KTool.SetActive(self.MatchingNode, true)
        coroutine.yield(WaitForSeconds(1))
        KTool.SetActive(self.MatchingNode, false)

        GameUtils.Request(Interfaces.PhoneEvent, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                self._isDrawing = false
                GameUtils.Toast(localize("今天能量用完了，明天再来看看吧。"))
                return
            end
            local jsonData = response.data
            if jsonData.refId == nil then
                self._isDrawing = false
                GameUtils.Toast(localize("今天能量用完了，明天再来看看吧。"))
                return
            end
            
            self:CheckEvent(jsonData)
            self._isDrawing = false
        end)
    end)
end

--摇一摇开始前重置一下状态
function UIFeelingNaughtyDialog:RefeshState()
    KTool.SetActive(self.IconGood, false)
    KTool.SetActive(self.Btnopen, false)
    KTool.SetActive(self.Chat, false)
    KTool.SetActive(self.BtnArrow, false)
    KTool.SetActive(self.slider, false)
    KTool.SetActive(self.AudioNode, false)
    KTool.SetActive(self.AudioNode, false)
    KTool.SetActive(self.BtnPlay, false)
    KTool.SetActive(self.BtnPlayToggle, false)
    KTool.SetActive(self.PanelGroup, false)
    KTool.SetActive(self.Txtdialogue, true)
end

--处理事件
function UIFeelingNaughtyDialog:CheckEvent(data)
    if not data then
        return 
    end
    self._curEventVo = PhoneUtils.GetPhoneRandomEventVo(data.refId)
    if not self._curEventVo then
        return
    end
    CfUtils.FillText(self.TxtName, self._curEventVo.name)
    CfUtils.FillText(self.Txtdialogue, self._curEventVo.descr)
    
    local type = checkNumber(data.type)
    if type == Constants.PhoneEventType.Chat then
        local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._curEventVo.npcId)
        local headPath =  CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId)
        CfUtils.FillImage(self.IconHead, headPath)
        KTool.SetActive(self.Chat, true)
        self:FillChat()
    else --除了chat其他四个是通用的，避免重复代码将icon绘制提取出来
        CfUtils.FillImage(self.IconGood, self._curEventVo.icon)
        KTool.SetActive(self.IconGood, true)
        if type == Constants.PhoneEventType.RedPack then
            self:FillRedPack(data)
        elseif type == Constants.PhoneEventType.Sound then
            self:FillSound(data)
        elseif type == Constants.PhoneEventType.Video then
            self:FillVideo(data)
        elseif type == Constants.PhoneEventType.PostCard then
            self:FillPostCard(data)
        end
    end
    KTool.SetActive(self.PanelGroup, true)
end

--红包
function UIFeelingNaughtyDialog:FillRedPack(data)
    self._isDontDrawReward = true
    KTool.SetActive(self.Btnopen, true)
    SetButtonAction(self.Btnopen, function()
        self._isDontDrawReward = false
        self:RefeshState()
        local rewards = data.rewards
        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = rewards}})
        GoodsUtils.DrawRewards(rewards)
    end)
end

--聊天
function UIFeelingNaughtyDialog:FillChat()
