    SetButtonAction(self.BtnArrow, function()
        CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIFeelingNaughtyFrameMessageDialog, parameters = {topicId = self._curEventVo.id, catId = self._curEventVo.npcId}})
    end)
end

--录音
function UIFeelingNaughtyDialog:FillSound(data)
    KTool.SetActive(self.Txtdialogue, false)

    local strs = CfUtils.Split(data.url, "/")
    local md5 = ""
    if strs then
        local md5Strs = CfUtils.Split(strs[#strs], ".")
        if md5Strs then
            md5 = checkString(md5Strs[1])
        end
    end
    local isSoundLoadFinish = false
    local UISoundPlayer = GameUtils.ShowSoundPlayer(data.url, md5, "", 24, nil, nil, function(length)
        local totalFmtTimeMin, totalFmtTimeSec = math.modf(length / 60)
        totalFmtTimeSec = checkInt(totalFmtTimeSec * 60)
        self.TxtTime.text = string.format("%s:%s/%s:%s", 0, 00, totalFmtTimeMin, totalFmtTimeSec)
        KTool.SetActive(self.AudioNode, true)
        KTool.SetActive(self.BtnPlayToggle, true)
        KTool.SetActive(self.slider, true)
        isSoundLoadFinish = true
    end)
    table.insert(self.GCList, UISoundPlayer.gameObject)
    local UISoundPlayerEnv = UISoundPlayer.Env
    SetToggleValueChanged(self.BtnPlayToggle, function(value)
        --CS.Engine.Wwise.AudioManager.Instance:StopMusic()
        if isSoundLoadFinish then
            if isNull(self.soundTime) then
                self.soundTime = UISoundPlayerEnv:GetLength()
            end
            if value then
                local playTime = UISoundPlayerEnv:GetTime() --当前播放的秒数
                if playTime > 0 and playTime < self.soundTime then
                    UISoundPlayerEnv:UnPause()
                else
                    UISoundPlayerEnv:Play()
                end
                self:StartSoundPlayProgress(playTime)
            else
                UISoundPlayerEnv:Pause()
                if not isNull(self.timerSound) then
                    CDTimerModule:RemoveCD(self.timerSound)
                    self.timerSound = nil
                end
            end
        end
    end)
end

