function UIFeelingNaughtyDialog:PlayShakeRobotAnim() --点击摇一摇机器人播放动画
    self._coAnim = cs_coroutine.start(function()
        self.robotAnim:Play("whitecat_select_wudizuo")
        coroutine.yield(WaitForSeconds(self.clickAnimTime))
        self.robotAnim:Play("whitecat_idle_wudizuo")
    end)
end

function UIFeelingNaughtyDialog:StartSoundPlayProgress(startTime)--刷新时间和进度条,参数为播放时的那一刻
    local leftTime = self.soundTime - startTime --剩余时间
    local totalFmtTimeMin, totalFmtTimeSec = math.modf(self.soundTime / 60)
    totalFmtTimeSec = checkInt(totalFmtTimeSec * 60)
    if not isNull(self.timerSound) then
        CDTimerModule:RemoveCD(self.timerSound)
        self.timerSound = nil
    end
    self.timerSound = CDTimerModule:AddCD(1, function (count, id)
        --printInfo("count-------->>"..count)
        local curTime = count + startTime
        local curFmtTimeMin, curFmtTimeSec = math.modf(curTime / 60)
        curFmtTimeSec = checkInt(curFmtTimeSec * 60)
        self.TxtTime.text = string.format("%s:%s/%s:%s", curFmtTimeMin, curFmtTimeSec, totalFmtTimeMin, totalFmtTimeSec)
        local progress = curTime / self.soundTime
        self.slider.value = progress
        if count == leftTime then --语音播放完成
            self.BtnPlayToggle.isOn = false
            --CS.Engine.Wwise.AudioManager.Instance:PlayMusic('bgm_mainmenu')
        end
    end, leftTime, true, true, false)
end

function UIFeelingNaughtyDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(true, false)
    end))
    return coWait
end

--手动回收创建出的GameObject
function UIFeelingNaughtyDialog:GarbageCollect()
    if isNull(self.GCList) then
        return
    end
    for k, v in pairs(self.GCList) do
        CS.UnityEngine.GameObject.Destroy(v.gameObject)
    end
end

function UIFeelingNaughtyDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --CfUtils.SetTopCommonActive(false, false)
        if not isNull(self) then--关闭协程
            if self._coAnim then
                cs_coroutine.stop(self._coAnim)
            end
            if self._co then
                cs_coroutine.stop(self._co)
            end
        end
        if not isNull(self.timerSound) then--关闭计时器
            CDTimerModule:RemoveCD(self.timerSound)
            self.timerSound = nil
        end
        phoneComp:SetYaoyiyaoReplyIndex({
            curMessageId = 0,
            replyIndexs = {},                        --回复的下标数组
        })
        if self.roleCamera then
            self.roleCamera.targetTexture = nil
        end
        if self.renderTexture then
            CS.UnityEngine.RenderTexture.ReleaseTemporary(self.renderTexture)
        end
        
        self:GarbageCollect()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingNaughtyDialog
